import { getEnv } from "@/env";
import { originFrom } from "@/lib/site-origin";

/**
 * Public SEO files are generated by Django (it knows the catalogue); Start serves them on
 * the one public origin. The forwarded host comes from `SITE_URL` when configured, so a
 * spoofed header cannot poison a cached copy. Only successful responses are cacheable.
 */
export function seoHandler(path: string) {
  return async ({ request }: { request: Request }) => {
    const env = getEnv();
    const origin = env.SITE_URL ? new URL(env.SITE_URL) : new URL(originFrom(request));
    const headers = new Headers({
      "x-forwarded-host": origin.host,
      "x-forwarded-proto": origin.protocol.slice(0, -1),
    });
    let res: Response;
    try {
      res = await fetch(new URL(path, env.API_INTERNAL_URL), { headers });
    } catch {
      return new Response("Upstream unavailable", {
        status: 502,
        headers: { "cache-control": "no-store" },
      });
    }
    return new Response(res.body, {
      status: res.status,
      headers: {
        "content-type": res.headers.get("content-type") ?? "text/plain; charset=utf-8",
        "cache-control": res.ok ? "public, max-age=3600" : "no-store",
      },
    });
  };
}
